export type UiEvent = { stream: string; t: number; t_end?: number; kind?: string; text?: string; seq?: number; row?: string } | null;
/** 窓・AI ごとのマウスのカーソル */
export type UiPointer = { key: string; t: number; source: "capture" | "recording" | null; name: string | null; role: string | null; client: number | null; time: number };
export type UiSampling = { expressions: Array<{ expr: string; plot: boolean; axis: "left" | "right" }>; rate_hz: number | null } | null;
/** 画面の状態（ui.state.get。rev は変わるたびに 1 増える） */
export type UiState = { rev: number; view: UiView; cursors: UiCursors; rows: Array<string> | null; event: UiEvent; frame: number; sampling: UiSampling; dashboard: UiDashboard; fpga_signals: FpgaSignalDefs | null; system: UiSystem; pointers: Array<UiPointer>; panel: { id: string; seq: number } | null };
export type UiSystem = { watches: Array<{ name: string; address: number }>; conditions: Array<{ name: string; expr: string }> } | null;
export type UiView = { source: "capture" | "recording"; t0: number; t1: number } | null;
/** CFI の巻き戻しをそこで止めた理由（fprobe.dwarf.unwind.Unwinder.unwind） */
export type UnwindStop = { reason: "max_frames"; max_frames: number } | { reason: "no_cfi"; pc: number } | { reason: "not_available"; detail: string } | { reason: "return_address"; value: number } | { reason: "cfa_below_sp"; cfa: number; sp: number } | { reason: "pc_zero" } | { reason: "repeated_frame"; pc: number; sp: number };
/** DWARF の型で読んだ値（fprobe.dwarf.values.decode の形。kind で種類が決まる） */
export type Value = { kind: "int"; value: number } | { kind: "float"; value: number | "nan" | "inf" | "-inf" } | { kind: "bool"; value: boolean } | { kind: "bytes"; hex: string } | { kind: "enum"; name: string | null; value: number } | { kind: "pointer"; address: number; to: string; deref?: boolean; symbol?: string; string?: string | null; string_end?: "limit" | "unreadable"; string_limit?: number } | { kind: "struct"; members: { [key: string]: Value } } | { kind: "array"; element_type?: string; length: number; items: Array<Value>; string?: string } | { kind: "unavailable"; reason: string };
/** 引数・ローカル変数 1 つ（line = 宣言の行、address = メモリ上なら番地） */
export type Variable = { name: string; type: string; value: Value; line?: number; address?: number };
/** ターゲットの電圧の読み（aux_mcu.AuxReading.as_dict） */
export type VoltageReading = { volts: number | null; over_range: boolean; live: boolean; samples: number; samples_before: number; window_s: number; errors: number };
/** 電圧の統計（fprobe.voltage.stats。V。値が無ければ min・max・mean は null） */
export type VoltageStats = { count: number; min: number | null; max: number | null; mean: number | null };
/** 見張りが最後に見たターゲットの状態（target.state の通知と同じ: target.status の応答 + run = コアを動かし得る操作が終わった回数。未接続は DISCONNECTED と、USB を開き直した後なら link_lost） */
